    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

























    @Test
    public void testEnumSet_Shortcut() {
        // EnumSet is special: if rawBase is EnumSet, return baseType
        JavaType baseType = typeFactory.constructCollectionType(EnumSet.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, EnumSet.class);
        // The logic says: if (rawBase == EnumSet.class) return baseType;
        // Since we are passing EnumSet as subclass, and rawBase is EnumSet, it triggers optimization at start
        // But if we bypassed optimization, the EnumSet check is there.
        assertSame(baseType, result);
    }






}

